// Calabi-Yau: sezione 2D della quintica di Fermat, n = 5 -> 25 patch.
// E' la figura canonica delle illustrazioni sulla teoria delle stringhe.
//   z1^5 + z2^5 = 1,  con z1,z2 complessi
// Per ogni coppia di radici quinte dell'unita' (k1,k2) una patch:
//   z1 = e^(2 pi i k1/5) * (cos w)^(2/5)
//   z2 = e^(2 pi i k2/5) * (sin w)^(2/5)     con w = u + i v
//
// SUPERFICIE 4D VERA: la quarta coordinata NON viene mescolata qui dentro.
// Im(z2) viene restituita come componente w del vec4, cosi' la proiezione e le
// rotazioni 4D restano all'interfaccia (dock Equations / rotazioni 4D).

float k1 = mod(float(mesh), 5.0);
float k2 = floor(float(mesh) / 5.0);
float p  = 2.0 / 5.0;

// w = u + i v;  cos(w) e sin(w) complessi
vec2 cw = vec2( cos(u) * cosh(v), -sin(u) * sinh(v));
vec2 sw = vec2( sin(u) * cosh(v),  cos(u) * sinh(v));

// Potenza complessa in forma polare. Sul dominio dichiarato Re(cos w) e
// Re(sin w) restano POSITIVE: l'argomento sta in (-pi/2, pi/2), lontano dal
// salto di atan, quindi niente taglio di ramo ne' cuciture fra patch.
float rc = safePow(length(cw), p);
float tc = p * atan(cw.y, cw.x);
float rs = safePow(length(sw), p);
float ts = p * atan(sw.y, sw.x);

// Radici quinte dell'unita': e^(2 pi i k/5)
float a1 = 2.0 * pi * k1 / 5.0;
float a2 = 2.0 * pi * k2 / 5.0;

vec2 z1 = rc * vec2(cos(tc + a1), sin(tc + a1));
vec2 z2 = rs * vec2(cos(ts + a2), sin(ts + a2));

// (Re z1, Re z2, Im z1) in R^3 + Im z2 come quarta coordinata
return vec4(z1.x,
            z2.x,
            z1.y,
            z2.y);
